// @ts-nocheck
// GENERATED by scripts/import_malloy.mjs from the malloy-render library — do not edit.
// Only the imports are rewritten (remotion frame hooks -> ../remotionShim, google fonts ->
// ../googleFonts, zod schema removed since its fields now live in the adapter's params).
import React, { useMemo } from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  interpolate,
  spring,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadInter = makeLoadFont('Inter');
const loadRobotoMono = makeLoadFont('RobotoMono');
import { evolvePath, getPointAtLength } from "@remotion/paths";

// Module-level font loading
const { fontFamily: interFamily } = loadInter();
const { fontFamily: robotoMonoFamily } = loadRobotoMono();



export type DynamicLineGraphProps = Record<string, any>;

const DynamicLineGraph: React.FC<DynamicLineGraphProps> = ({
  backgroundColor = "#0a0a0a",
  transparentBackground = false,
  durationInSeconds = 8,
  title = "Real-time Performance Data",
  subtitle = "Metric analysis over time",
  lineColor = "#00f0ff",
  gridColor = "#333333",
  textColor = "#e5e5e5",
  markerColor = "#ffffff",
  glowColor = "#60a5fa",
  chartData = [10, -5, 12, 40, 65, 30, 110, 45, 35, 20, 25],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  const bgColor = transparentBackground ? undefined : backgroundColor;

  // Layout Constants
  const paddingX = width * 0.12;
  const paddingY = height * 0.2;
  const graphWidth = width - paddingX * 2;
  const graphHeight = height - paddingY * 2;
  const graphBottomY = height - paddingY;

  // Safe data and calculations
  const layout = useMemo(() => {
    const safeData = chartData.length >= 2 ? chartData : [10, 20, 30, 40, 50];
    const rawMin = Math.min(...safeData);
    const rawMax = Math.max(...safeData);
    const range = rawMax - rawMin;

    let paddedMin = rawMin - range * 0.1;
    let paddedMax = rawMax + range * 0.1;

    // Prevent division by zero if all values are identical
    if (range === 0) {
      paddedMin = rawMin - 10;
      paddedMax = rawMax + 10;
    }

    const points = safeData.map((val, i) => {
      const x = paddingX + (i / (safeData.length - 1)) * graphWidth;
      const y =
        height -
        paddingY -
        ((val - paddedMin) / (paddedMax - paddedMin)) * graphHeight;
      return { x, y, val };
    });

    const pathString =
      `M ${points[0].x} ${points[0].y} ` +
      points
        .slice(1)
        .map((p) => `L ${p.x} ${p.y}`)
        .join(" ");

    let currentLen = 0;
    const vertexLengths = [0];
    for (let i = 1; i < points.length; i++) {
      const dx = points[i].x - points[i - 1].x;
      const dy = points[i].y - points[i - 1].y;
      currentLen += Math.sqrt(dx * dx + dy * dy);
      vertexLengths.push(currentLen);
    }
    const totalLength = currentLen;

    const yGridLines = Array.from({ length: 6 }).map((_, i) => {
      const val = paddedMin + (i / 5) * (paddedMax - paddedMin);
      const y =
        height -
        paddingY -
        ((val - paddedMin) / (paddedMax - paddedMin)) * graphHeight;
      return { val, y, i };
    });

    return { points, pathString, vertexLengths, totalLength, yGridLines };
  }, [chartData, width, height, paddingX, paddingY, graphWidth, graphHeight]);

  // Animation Timings
  const totalFrames = fps * durationInSeconds;
  const drawStart = 30;
  const drawDuration = Math.max(30, totalFrames - drawStart - 60);
  const drawEnd = drawStart + drawDuration;

  // Path Animation Progress
  const progress = interpolate(frame, [drawStart, drawEnd], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  const evolution = evolvePath(progress, layout.pathString);
  const currentLength = progress * layout.totalLength;

  const currentPoint = useMemo(() => {
    if (layout.totalLength === 0) return layout.points[0];
    try {
      const safeLength = Math.max(
        0,
        Math.min(layout.totalLength, currentLength)
      );
      return getPointAtLength(layout.pathString, safeLength);
    } catch (e) {
      return layout.points[0];
    }
  }, [layout.pathString, layout.totalLength, currentLength, layout.points]);

  const indicatorOpacity = interpolate(
    frame,
    [drawStart, drawStart + 10],
    [0, 1],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  const xAxisLength = interpolate(frame, [0, 20], [0, graphWidth], {
    extrapolateRight: "clamp",
  });
  const yAxisLength = interpolate(frame, [0, 20], [0, graphHeight], {
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill
      style={{ backgroundColor: bgColor, transition: "none", overflow: "hidden" }}
    >
      <svg
        width={width}
        height={height}
        style={{ position: "absolute", transition: "none" }}
      >
        {/* Horizontal Grid Lines & Y-Axis Labels */}
        {layout.yGridLines.map((line) => {
          const opacity = interpolate(
            frame,
            [5 + line.i * 2, 15 + line.i * 2],
            [0, 1],
            { extrapolateRight: "clamp" }
          );
          const xOffset = interpolate(
            frame,
            [5 + line.i * 2, 15 + line.i * 2],
            [-10, 0],
            { extrapolateRight: "clamp" }
          );

          return (
            <g key={`y-grid-group-${line.i}`}>
              <line
                x1={paddingX}
                y1={line.y}
                x2={width - paddingX}
                y2={line.y}
                stroke={gridColor}
                strokeWidth={1}
                strokeDasharray="4 4"
                opacity={opacity * 0.15}
                style={{ transition: "none" }}
              />
              <text
                x={paddingX - 20 + xOffset}
                y={line.y + 5}
                fill={textColor}
                opacity={opacity * 0.7}
                fontSize={16}
                fontFamily={robotoMonoFamily}
                textAnchor="end"
                style={{ transition: "none" }}
              >
                {Math.round(line.val)}
              </text>
            </g>
          );
        })}

        {/* Vertical Grid Lines & X-Axis Labels */}
        {layout.points.map((p, i) => {
          const opacity = interpolate(
            frame,
            [15 + i * 2, 25 + i * 2],
            [0, 1],
            { extrapolateRight: "clamp" }
          );
          const yOffset = interpolate(
            frame,
            [15 + i * 2, 25 + i * 2],
            [10, 0],
            { extrapolateRight: "clamp" }
          );

          return (
            <g key={`x-grid-group-${i}`}>
              <line
                x1={p.x}
                y1={paddingY}
                x2={p.x}
                y2={graphBottomY}
                stroke={gridColor}
                strokeWidth={1}
                strokeDasharray="4 4"
                opacity={opacity * 0.15}
                style={{ transition: "none" }}
              />
              <text
                x={p.x}
                y={graphBottomY + 40 + yOffset}
                fill={textColor}
                opacity={opacity * 0.7}
                fontSize={16}
                fontFamily={robotoMonoFamily}
                textAnchor="middle"
                style={{ transition: "none" }}
              >
                {i}s
              </text>
            </g>
          );
        })}

        {/* X Axis Main Line */}
        <line
          x1={paddingX}
          y1={graphBottomY}
          x2={paddingX + xAxisLength}
          y2={graphBottomY}
          stroke={textColor}
          strokeWidth={2}
          opacity={0.4}
          style={{ transition: "none" }}
        />

        {/* Y Axis Main Line */}
        <line
          x1={paddingX}
          y1={graphBottomY}
          x2={paddingX}
          y2={graphBottomY - yAxisLength}
          stroke={textColor}
          strokeWidth={2}
          opacity={0.4}
          style={{ transition: "none" }}
        />

        {/* Title Text */}
        <text
          x={paddingX}
          y={paddingY - 80}
          fill={textColor}
          fontFamily={interFamily}
          fontSize={48}
          fontWeight="bold"
          opacity={interpolate(frame, [0, 20], [0, 1], {
            extrapolateRight: "clamp",
          })}
          style={{ transition: "none" }}
        >
          {title}
        </text>

        {/* Subtitle Text */}
        <text
          x={paddingX}
          y={paddingY - 35}
          fill={textColor}
          opacity={interpolate(frame, [5, 25], [0, 0.6], {
            extrapolateRight: "clamp",
          })}
          fontFamily={interFamily}
          fontSize={24}
          style={{ transition: "none" }}
        >
          {subtitle}
        </text>

        {/* Animated Data Line */}
        <path
          d={layout.pathString}
          fill="none"
          stroke={lineColor}
          strokeWidth={4}
          strokeLinejoin="round"
          strokeLinecap="round"
          strokeDasharray={evolution.strokeDasharray}
          strokeDashoffset={evolution.strokeDashoffset}
          opacity={progress > 0 ? 1 : 0}
          style={{ transition: "none" }}
        />

        {/* Current Value Indicator Line (Vertical Dashed) */}
        {progress > 0 && (
          <line
            x1={currentPoint.x}
            y1={graphBottomY}
            x2={currentPoint.x}
            y2={currentPoint.y}
            stroke={glowColor}
            strokeWidth={1.5}
            strokeDasharray="4 4"
            opacity={indicatorOpacity * 0.5}
            style={{ transition: "none" }}
          />
        )}

        {/* Leading Glow Dot */}
        {progress > 0 && (
          <g
            transform={`translate(${currentPoint.x}, ${currentPoint.y})`}
            opacity={indicatorOpacity}
            style={{ transition: "none" }}
          >
            <circle r={24} fill={glowColor} opacity={0.15} style={{ transition: "none" }} />
            <circle r={12} fill={glowColor} opacity={0.4} style={{ transition: "none" }} />
            <circle r={6} fill={markerColor} style={{ transition: "none" }} />
          </g>
        )}

        {/* Elastic Vertex Markers */}
        {layout.points.map((p, i) => {
          const vFrame =
            drawStart +
            (layout.vertexLengths[i] / layout.totalLength) * drawDuration;

          const scale = spring({
            fps,
            frame: frame - vFrame,
            config: { damping: 8, mass: 0.6, stiffness: 120 },
          });

          return (
            <circle
              key={`marker-${i}`}
              cx={p.x}
              cy={p.y}
              r={Math.max(0, 8 * scale)}
              fill={backgroundColor}
              stroke={markerColor}
              strokeWidth={3}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>
    </AbsoluteFill>
  );
};

export default DynamicLineGraph;